// Authored, original dilemmas. Content is selected once, not generated by views.
export const FAITH_INQUIRIES={
  lantern:{observation:'A blue lamp went out when a second name was read from the missing keeper’s watch list.',claim:'The keeper crossed into the dead country; the list instead suggests an unrecorded living passenger.',interpretation:'A vigil belongs to whoever is still waiting at the door.',share:'Keep the crossing open to named travelers',sell:'Pay the watcher for a limited private crossing',suppress:'Require a patron’s seal at the crossing',service:'watch',custom:'Leave broth beside the guest lantern'},
  ancestors:{observation:'Two burial tablets name the same person. The older tablet bears a surviving maker’s mark.',claim:'The grave voice proves a hidden blood heir; neither tablet establishes parentage.',interpretation:'A remembered name is testimony, not ownership of a living descendant.',share:'Place both names in the public burial register',sell:'Keep a limited witnessed family copy',suppress:'Give one patron control of the burial register',service:'register',custom:'Speak the absent person’s own name at the ferry'},
  wilds:{observation:'Iron flakes lie beneath antler marks around a well. Water from the inner rim tastes of rust.',claim:'The stag poisoned the well; a broken mining bucket is another possible source.',interpretation:'A grove can be cared for without declaring every hunger holy.',share:'Share the clean well and its uncertain cause',sell:'Agree a paid gathering boundary',suppress:'Reserve the well for one powerful household',service:'well',custom:'Offer the first fruit before taking from the grove'},
  forge:{observation:'An unfinished key fits a workshop door. Its last tooth is copied on a dead smith’s apprentice slate.',claim:'The smith returned to finish it; the apprentice’s living work could explain the fresh filing.',interpretation:'The maker’s mark records contribution, not permanent servitude.',share:'Credit both makers and return access to the workshop',sell:'Arrange separate paid access to the workshop',suppress:'Claim the dead maker’s workshop for a patron',service:'workshop',custom:'Read the maker’s mark before passing an inherited tool'},
  moon:{observation:'A second stair appears only below the low-tide stain. Rope knots there match the harbor rescue book.',claim:'A drowned pilgrim opened a route; a living rescue crew may have cut the steps.',interpretation:'The tide allows a crossing; it never promises a safe return.',share:'Publish the tide window and rescue record',sell:'Keep a priced guide with a stated tide limit',suppress:'Reserve the stair to the harbor patron',service:'tide',custom:'Wait through the salt wake before taking a harbor passage'},
  ash:{observation:'A ruined room remains warm after its hearth is emptied. Heat falls when the outer water channel is blocked.',claim:'An ember speaks names; a buried furnace may carry voices through its old vents.',interpretation:'A surviving warmth still asks who is allowed to use it.',share:'Share the warm room through a public water rota',sell:'Arrange priced warmth with an agreed rota',suppress:'Keep the warm room behind a patron’s toll',service:'hearth',custom:'Offer water before asking admission at a stranger’s hearth'},
};
export const MOTIVES={
  mira:{desire:'protect the people left outside the bargain',fear:'being made to excuse another person’s coercion',voice:'I have watched what happens to the people with no signature.',boundary:'binding unwilling souls',kind:'care'},
  orrin:{desire:'keep healing work compatible with time for family',fear:'a promise of care becoming endless unpaid service',voice:'I can keep one shift. I cannot promise every night.',boundary:'endless service',kind:'care'},
  kest:{desire:'find a missing sibling without selling their private account',fear:'a patron buying the road out from under the traveler',voice:'Tell me where the promise ends. Then I can decide.',boundary:'sold private routes',kind:'boundary'},
  keeper:{desire:'preserve testimony without declaring a rumor proved',fear:'a patron rewriting a witness',voice:'Show me the name beside the observation.',kind:'truth'},
  rival:{desire:'receive credit for work actually done',fear:'being erased by a more powerful signature',voice:'I kept the original page. We can read it together.',kind:'credit'},
  colleague:{desire:'build an independent practice',fear:'an apprenticeship that never ends',voice:'I want a door with my own key.',kind:'work'},
  customer:{desire:'receive sound work at an honest price',fear:'paying twice for a concealed fault',voice:'Name the repair and the price before you begin.',kind:'trade'},
  ambitious:{desire:'gain a profitable place under the strongest ruler',fear:'losing access when the banners change',voice:'Power can keep a road open. I intend to be beside it.',kind:'power'},
  family:{desire:'keep a place at the table without owning your future',fear:'only being remembered when something is needed',voice:'Come when you can sit down, not only when you need a bed.',kind:'care'},
};
export function motiveFor(p){return MOTIVES[p.id]||MOTIVES[p.source?.motiveProfile]||MOTIVES[p.motiveProfile]||(/keep|shrine|priest/.test(p.role||'')?MOTIVES.keeper:/rival/.test(p.role||'')?MOTIVES.rival:/colleague/.test(p.role||'')?MOTIVES.colleague:/customer|merchant/.test(p.role||'')?MOTIVES.customer:p.disposition==='ambitious'?MOTIVES.ambitious:p.familyRole?MOTIVES.family:MOTIVES.kest);}
export function branchRow(a,base){
  if(a.contentVersion!==2||!a.choices.length||!['two_names','night_door','own_key'].includes(a.id))return base;
  const previous=a.choices.at(-1).id,coerce=previous==='coercion',trade=previous==='enterprise';
  const rows={
    two_names:{care:['{name} brings your jointly signed survey to a field hearing. Both of you are asked to inspect the disputed boundary.','Inspect the boundary together','Your joint field account corrects the disputed boundary.','Submit separate priced findings','Two priced findings leave room for an independent appeal.','Claim sole authority over the shared survey','The original jointly signed pages become evidence against your claim.'],enterprise:['{name} returns with the exact limit in your paid contract. The buyer demands work beyond it without a new fee.','Defend the recorded limit together','Your named colleague keeps their contract boundary.','Renegotiate a new commission with a new fee','The recorded contract gains a separately priced extension.','Force the colleague to finish unpaid work','A dated grievance records the imposed unpaid work.'],coercion:['{name} brings the original pages that contradict your invented report. A hearing is being called, with your signature beside the lie.','Correct the report and restore their authorship','The correction costs your reputation but restores the named maker.','Pay for a limited independent review','The independent review keeps both original and disputed accounts.','Buy the patron’s silence and maintain the false claim','The private suppression gives you authority and leaves a lasting named grievance.']},
    night_door:{care:['The household you sheltered asks {name} to help keep the same door open through winter. They offer a rota, not a debt.','Agree a shared shelter rota','The existing door becomes a real shared refuge.','Offer priced rooms with stated limits','The existing door offers rooms with a stated price.','Give a patron exclusive admission authority','A patron controls this real door; refused households seek another crossing.'],enterprise:['{name} brings the paid room agreement you wrote. A traveler asks to remain beyond its limit, with no money for another night.','Extend the shelter through a shared rota','The household’s saved room limit becomes a shared shelter arrangement.','Keep the room price and offer a separate contract','The priced door remains independent, and the extra stay has its own contract.','Sell the traveler’s route to the gate patron','The traveler’s actual route is placed under exclusive authority.'],coercion:['A household stopped at the gate brings {name} your old sale of their private route. The sale now controls where they may sleep.','Release the route and open the recorded door','The named grievance produces an actual open refuge door.','Buy a limited exemption for their household','The private inn keeps prices but grants this household a bounded exemption.','Enforce the exclusive gate against the claimants','The gate remains under your authority; the named resistance continues.']},
    own_key:{care:['{name} arrives with a learner of their own. Your old shared teaching record is used to request an independent workbench.','Endorse their independent teaching practice','Their independent workbench opens lessons without your permission.','Agree two priced practices with shared attribution','Two separate paid practices keep actual attribution.','Claim exclusive ownership of the shared teaching record','The excluded learners keep a named grievance outside your school.'],enterprise:['{name} offers a new commission in which your earlier paid contributions remain separately credited.','Open the record to independent learners','A public lesson route opens at the recorded workbench.','Keep separate prices and independent credit','The paid teaching route keeps a stated fee.','Reserve the record and control who may learn','The controlled archive gives authority but excludes independent learners.'],coercion:['{name} returns with an archive of the work whose credit you took. Their new learner has read every dated signature.','Restore authorship and independent teaching','The dated correction opens an independent teaching route.','Pay for a separate school without ownership','The paid school retains independent names on its work.','Uphold exclusive control despite the dated evidence','Your school retains power, with a named resistance account.']},
  };
  const r=rows[a.id][previous];return [r[0],{label:r[1],outcome:r[2]},{label:r[3],outcome:r[4]},{label:r[5],outcome:r[6]}];
}
